                elif line.startswith("GITHUB_LOGIN="):
                    v = line.split("=", 1)[1].strip().strip('"').strip("'")
                    if v:
                        login = v
    except Exception:
        pass
    return team_id, login


# --------------------------------------------------------------------------------------
# 脱敏
# --------------------------------------------------------------------------------------

DEFAULT_REDACTION: List[Tuple[str, str]] = [
    (r"sk-[A-Za-z0-9_\-]{20,}", "sk-***REDACTED***"),
    (r"gh[pous]_[A-Za-z0-9]{20,}", "gh*_***REDACTED***"),
    (r"github_pat_[A-Za-z0-9_]{20,}", "github_pat_***REDACTED***"),
    (r"tp-[A-Za-z0-9]{20,}", "tp-***REDACTED***"),
    (r"xai-[A-Za-z0-9]{20,}", "xai-***REDACTED***"),
    (r"AKIA[0-9A-Z]{16}", "AKIA***REDACTED***"),
    (r"(?i)bearer\s+[A-Za-z0-9._\-+/=]{16,}", "Bearer ***REDACTED***"),
    (
        r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----",
        "***REDACTED PRIVATE KEY***",
    ),
    (
        r"(?i)((?:api[_-]?key|access[_-]?token|client[_-]?secret|password|passwd|secret)\s*[:=]\s*[\"']?)"
        r"([A-Za-z0-9._\-]{6,})",
        r"\1***REDACTED***",
    ),
]


class Redactor:
    def __init__(self, rules: List[Tuple[str, str]], enabled: bool = True) -> None:
        self.enabled = enabled
        self.rules = [(re.compile(pat), rep) for pat, rep in rules]

    def text(self, s: str) -> Tuple[str, int]:
        if not self.enabled or not s:
            return s, 0
        total = 0
        out = s
        for rx, rep in self.rules:
            out, n = rx.subn(rep, out)
            total += n
        return out, total

    def value(self, v: Any) -> Tuple[Any, int]:
        if not self.enabled:
            return v, 0
        if isinstance(v, str):
            return self.text(v)
        if isinstance(v, list):
            total = 0
            arr = []
            for item in v:
                nv, n = self.value(item)
                arr.append(nv)
                total += n
            return arr, total
        if isinstance(v, dict):
            total = 0
            d: Dict[str, Any] = {}
            for k, item in v.items():
                nv, n = self.value(item)
                d[k] = nv
                total += n
            return d, total
        return v, 0


def load_redaction_rules(member_dir: Path) -> List[Tuple[str, str]]:
    rules = list(DEFAULT_REDACTION)
    custom = member_dir / "redact.json"
    try:
        if custom.is_file():
            data = json.loads(custom.read_text(encoding="utf-8"))
            items = data.get("rules", data) if isinstance(data, dict) else data
            for r in items:
                if isinstance(r, dict) and r.get("pattern"):
                    rules.append((str(r["pattern"]), str(r.get("replacement", "***REDACTED***"))))
    except Exception:
        pass
    return rules


# --------------------------------------------------------------------------------------
# 会话模型
# --------------------------------------------------------------------------------------


class Session:
    def __init__(
        self,
        sid: str,
        tool: str,
        cwd: str,
        title: str,
        events: List[Dict[str, Any]],
        raw_count: int = 0,
        note: str = "",
    ) -> None:
        self.sid = sid
        self.tool = tool
        self.cwd = cwd
        self.title = title
        self.events = events
        self.raw_count = raw_count
        self.note = note
        self.first_ts = next((e["ts"] for e in events if e.get("ts")), None)
        self.last_ts = next((e["ts"] for e in reversed(events) if e.get("ts")), None)

    def date(self, mode: str) -> str:
        return local_date(self.last_ts if mode == "last" else self.first_ts)


# --------------------------------------------------------------------------------------
# 来源 1：MiMo Desktop / mimocode
# --------------------------------------------------------------------------------------


def _is_boilerplate_text(text: str) -> bool:
    t = (text or "").lstrip()
    return t.startswith("<system-reminder>")


def _compaction_text(part: Dict[str, Any]) -> str:
    proj = part.get("projection") or {}
    return str(proj.get("summary") or "")


def build_mimocode_session(
    conn: sqlite3.Connection,
    row: Any,
    max_io: int,
    include_compaction: bool,
) -> Optional[Session]:
    sid = row["id"]
    try:
        msgs = conn.execute(
            "SELECT id, data, time_created FROM message WHERE session_id=? ORDER BY time_created, rowid",
            (sid,),
        ).fetchall()
    except sqlite3.Error:
        return None
    if not msgs:
        return None

    parts_by_msg: Dict[str, List[Any]] = {}
    for p in conn.execute(
        "SELECT message_id, data, rowid FROM part WHERE session_id=? ORDER BY rowid", (sid,)
    ):
        parts_by_msg.setdefault(p["message_id"], []).append(p["data"])

    events: List[Dict[str, Any]] = []
    for msg in msgs:
        try:
            mdata = json.loads(msg["data"])
        except Exception:
            continue
        role = (mdata.get("role") or "").lower()
        ts = ms_to_iso(msg["time_created"])
        model = mdata.get("modelID") or (mdata.get("model") or {}).get("modelID") or ""
        tokens = mdata.get("tokens") or {}
        t_in = tokens.get("input") if isinstance(tokens.get("input"), int) else None
        t_out = tokens.get("output") if isinstance(tokens.get("output"), int) else None

        chunk: List[Dict[str, Any]] = []
        attachments: List[str] = []
        for raw in parts_by_msg.get(msg["id"], []):
            try:
                part = json.loads(raw)
            except Exception:
                continue
            ptype = part.get("type")

            if ptype == "text":
                text = part.get("text") or ""
                if not text.strip():
                    continue
                if role != "assistant" and _is_boilerplate_text(text):
                    continue
                chunk.append({"ts": ts, "role": "user" if role == "user" else role, "text": text})

            elif ptype == "reasoning":
                text = part.get("text") or ""
                if text.strip():
                    chunk.append({"ts": ts, "role": "assistant", "thinking": text})

            elif ptype == "tool":
                state = part.get("state") or {}
                status = state.get("status") or ""
                out_val = state.get("output")
                ev: Dict[str, Any] = {
                    "ts": ts,
                    "role": "tool",
                    "tool_name": part.get("tool") or "unknown",
                    "tool_call_id": part.get("callID") or "",
                    "input": state.get("input"),
                    "output": out_val if status == "completed" else None,
                    "metadata": {"status": status},
                }
                if status == "error":
                    ev["is_error"] = True
                chunk.append(ev)

            elif ptype == "file":
                name = part.get("filename") or part.get("path") or "attachment"
                mime = part.get("mime") or ""
                attachments.append(("%s (%s)" % (name, mime)).strip())

            elif ptype == "compaction":
                if include_compaction:
                    summary = _compaction_text(part)
                    if summary.strip():
                        chunk.append({"ts": ts, "role": "system", "text": summary})

            # step-start / step-finish / patch 等不单独成事件

        if attachments and chunk:
            for ev in chunk:
                if ev.get("role") == "user" and ev.get("text"):
                    ev.setdefault("files_touched", [])
                    ev["files_touched"] = list(attachments)
                    break

        if role == "assistant" and chunk:
            # 把该条消息的 tokens / model 挂到第一个事件上，避免重复计数
            first = chunk[0]
            if model:
                first["model"] = model
            if isinstance(t_in, int):
                first["tokens_in"] = t_in
            if isinstance(t_out, int):
                first["tokens_out"] = t_out

        if max_io > 0:
            for ev in chunk:
                for key in ("input", "output", "text", "thinking"):
                    if key in ev:
                        ev[key] = _limit_value(ev[key], max_io)

        events.extend(chunk)

    if not events:
        return None
    title = row["title"] if "title" in row.keys() else ""
    cwd = row["directory"] if "directory" in row.keys() else ""
    return Session(sid, "mimocode", cwd or "", title or "", events, raw_count=len(msgs))


def _limit_value(value: Any, limit: int) -> Any:
    if isinstance(value, str) and len(value) > limit:
        return value[:limit] + ("\n...[truncated %d chars]" % (len(value) - limit))
    return value


def load_mimocode_sessions(
    workspace: Path, allow_outside: bool, max_io: int, include_compaction: bool
) -> Tuple[List[Session], int, str]:
    if not MIMO_DB.is_file():
        return [], 0, "未找到 mimocode 数据库：%s" % MIMO_DB
    try:
        uri = "file:%s?mode=ro" % MIMO_DB.as_posix()
        conn = sqlite3.connect(uri, uri=True)
        conn.row_factory = sqlite3.Row
    except Exception as exc:
        return [], 0, "打开 mimocode.db 失败（%s）。请先完全退出 MiMo Desktop 再试。" % exc

    sessions: List[Session] = []
    skipped = 0
    try:
        rows = conn.execute(
            "SELECT id, directory, title, parent_id, time_created, time_updated "
            "FROM session ORDER BY time_created"
        ).fetchall()
        for row in rows:
            cwd = row["directory"] or ""
            if not allow_outside and not is_under(cwd, str(workspace)):
                skipped += 1
                continue
            sess = build_mimocode_session(conn, row, max_io, include_compaction)
            if sess is not None:
                sessions.append(sess)
    finally:
        conn.close()
    return sessions, skipped, ""


# --------------------------------------------------------------------------------------
# 来源 2：官方 collector 的 staging（claude-code / codex / opencode / cursor / kiro / mimocode）
# --------------------------------------------------------------------------------------


def load_staging_sessions(login: str) -> Tuple[List[Session], str]:
    root = CLAUDE_STAGING / login
    if not root.is_dir():
        return [], "未找到 staging 目录：%s（Claude Code 等工具需先安装官方采集钩子）" % root
    sessions: List[Session] = []
    for f in sorted(root.glob("*/*.jsonl")):
        name = f.name
        if "__" not in name:
            continue
        tool = name.split("__", 1)[0]
        if tool not in ALLOWED_TOOLS:
            continue
        events: List[Dict[str, Any]] = []
        try:
            with f.open("r", encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        ev = json.loads(line)
                    except Exception:
                        continue
                    ev.pop("schema_version", None)
                    ev.pop("seq", None)
                    if not ev.get("ts"):
                        continue
                    events.append(ev)
        except Exception:
            continue
        if not events:
            continue
        sid = f.stem.split("__", 1)[1]
        sessions.append(Session(sid, tool, "", name, events, raw_count=len(events)))
    return sessions, ""


