def event_line(
    sess: Session,
    seq: int,
    ev: Dict[str, Any],
    team_id: str,
    login: str,
    redactor: Redactor,
) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "session_id": sess.sid,
        "team_id": team_id,
        "github_login": login,
        "tool": sess.tool,
        "seq": seq,
    }
    out.update(ev)
    out, count = redactor.value(out)
    if count:
        out["redacted_count"] = count
    return out


def write_session(
    sess: Session,
    out_root: Path,
    team_id: str,
    login: str,
    date_mode: str,
    redactor: Redactor,
    overwrite: bool,
) -> Optional[Dict[str, Any]]:
    date = sess.date(date_mode)
    target = out_root / date / ("%s__%s.jsonl" % (sess.tool, sess.sid))
    if target.exists() and not overwrite:
        return None
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_suffix(".jsonl.tmp")
    total_redacted = 0
    with tmp.open("w", encoding="utf-8", newline="\n") as fh:
        for i, ev in enumerate(sess.events):
            line = event_line(sess, i, ev, team_id, login, redactor)
            total_redacted += int(line.get("redacted_count", 0) or 0)
            fh.write(json.dumps(line, ensure_ascii=False) + "\n")
    tmp.replace(target)
    return {
        "path": target,
        "date": date,
        "event_count": len(sess.events),
        "redacted": total_redacted,
        "raw_count": sess.raw_count,
        "session": sess,
    }


def supersede_old(out_root: Path, sess: Session, keep: Path) -> List[Path]:
    moved: List[Path] = []
    for f in sorted(out_root.glob("*/*.jsonl")):
        if f == keep:
            continue
        if not f.stem.endswith("__" + sess.sid):
            continue
        if f.stem == keep.stem and f.parent == keep.parent:
            continue
        dest = out_root / ".superseded" / f.parent.name / f.name
        dest.parent.mkdir(parents=True, exist_ok=True)
        try:
            shutil.move(str(f), str(dest))
            moved.append(dest)
        except Exception:
            pass
    return moved


def rebuild_manifest(out_root: Path, team_id: str, login: str) -> Dict[str, Any]:
    manifest_path = out_root / "manifest.json"
    old: Dict[str, Any] = {}
    try:
        if manifest_path.is_file():
            old = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        old = {}
    old_by_sid: Dict[str, Dict[str, Any]] = {}
    for e in old.get("sessions") or []:
        if isinstance(e, dict) and e.get("session_id"):
            old_by_sid[str(e["session_id"])] = e

    entries: List[Dict[str, Any]] = []
    date_re = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    for f in sorted(out_root.glob("*/*.jsonl")):
        date_dir = f.parent.name
        if not date_re.match(date_dir):
            continue
        count = 0
        first_ts = last_ts = None
        sid = tool = model = None
        redacted_total = 0
        seq_ok = True
        prev_seq = -1
        try:
            with f.open("r", encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    count += 1
                    try:
                        ev = json.loads(line)
                    except Exception:
                        continue
                    if first_ts is None:
                        first_ts = ev.get("ts")
                        sid = ev.get("session_id")
                        tool = ev.get("tool")
                    last_ts = ev.get("ts") or last_ts
                    if not model and ev.get("model"):
                        model = ev.get("model")
                    redacted_total += int(ev.get("redacted_count", 0) or 0)
                    seq = ev.get("seq")
                    if not isinstance(seq, int) or seq != prev_seq + 1:
                        seq_ok = False
                    else:
                        prev_seq = seq
        except Exception:
            continue
        name_tool = f.name.split("__", 1)[0]
        sid = sid or f.stem
        entry: Dict[str, Any] = {
            "session_id": sid,
            "tool": tool or name_tool,
            "started_at": first_ts or now_iso(),
            "last_event_at": last_ts or first_ts or now_iso(),
            "event_count": count,
            "file_path": "logs/%s/%s/%s" % (login, date_dir, f.name),
            "collection_mode": "cli",
            "health": "ok" if seq_ok else "warn",
        }
        prev = old_by_sid.get(sid) or {}
        for k in ("raw_event_count", "data_completeness_warning"):
            if k in prev:
                entry[k] = prev[k]
        if model:
            entry["model"] = model
        if redacted_total:
            entry["redacted_count_total"] = redacted_total
        entries.append(entry)

    entries.sort(key=lambda e: str(e.get("started_at") or ""))
    manifest = {
        "schema_version": SCHEMA_VERSION,
        "team_id": team_id,
        "github_login": login,
        "generator": "manual-ai-log-exporter@%s" % EXPORTER_VERSION,
        "updated_at": now_iso(),
        "sessions": entries,
    }
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return manifest


