#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
openvela 2026 大赛 —— AI Coding 日志手动导出工具（单文件，无第三方依赖）

用途
----
把本机 AI 编程工具的真实会话，导出成大赛要求的 logs/<GITHUB_LOGIN>/<date>/<tool>__<sid>.jsonl
（schema v1.0，逐事件一行），并重建 manifest.json。导出目标是“预览优先、确认才写盘”，
避免误把私人对话提交进比赛仓库。

支持的数据来源
--------------
1) MiMo Desktop / mimocode  (tool id: mimocode)
   ~/.local/share/mimocode/mimocode.db  (SQLite: session / message / part)
   —— 这是本机用得最多的工具，支持完整导出（含工具入参/出参、thinking、tokens）。
2) Claude Code (tool id: claude-code)
   ~/.claude/contest-collector-staging/<login>/<date>/<tool>__<sid>.jsonl
   —— 官方 contest-log-collector 钩子已经写好的规范事件，这里做导入 + 重排 seq + 重建 manifest。
   —— 若该目录为空，说明钩子没装/没触发，请按官方手册 install.sh 安装后再来导出。
3) Codex CLI (tool id: codex)  —— 可选，需本机有 zstandard 或 zstd 命令
   ~/.codex/sessions/<yyyy>/<mm>/<dd>/rollout-*.jsonl.zst
4) OpenCode / Cursor / Kiro —— 官方钩子自己会写入 staging，本脚本会一并从 staging 导入。

典型用法（在 workspace 根目录，或任意位置加 --out）
---------------------------------------------------
  python export_ai_logs.py                     # 预览：列出本次将要导出的会话（不写盘）
  python export_ai_logs.py --list              # 只列清单（含被工作区闸门排除的会话数）
  python export_ai_logs.py --session ses_xxx   # 预览某个会话
  python export_ai_logs.py --today --confirm   # 导出今天结束的会话
  python export_ai_logs.py --since 2026-09-01 --confirm
  python export_ai_logs.py --all --confirm     # 导出全部（工作区内）
  python export_ai_logs.py --validate          # 只校验 logs 目录
  python export_ai_logs.py --scrub-existing --confirm   # 只对已有文件做脱敏

隐私与合规
----------
* 工作区闸门：MiMo 会话按 session.directory 判断，只有在 openvela 工作区（默认=本脚本所在目录，
  或其上层含 .repo 的目录）内的会话才会被采集；--allow-outside 可放开（不建议）。
* 密钥脱敏：默认对 sk-/ghp_/gho_/github_pat_/tp-/Bearer/私钥/api_key=... 等做替换，并在事件里写
  redacted_count；可在 logs/<login>/redact.json 追加自定义规则（官方同款约定）。
* 本工具永不执行 git push，只写本地文件。

退出码：0 成功 / 1 校验失败或写入失败 / 2 参数或环境问题
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import sqlite3
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

SCHEMA_VERSION = "1.0"
EXPORTER_VERSION = "1.0.0"

ALLOWED_TOOLS = {"opencode", "claude-code", "codex", "kiro", "mimocode", "cursor"}
ALLOWED_ROLES = {"user", "assistant", "tool", "system"}

DEFAULT_TEAM_ID = "contest2026_037_TensorFishSpecialActivityDivison"
DEFAULT_LOGIN = "LR-C11"

SCRIPT_DIR = Path(__file__).resolve().parent


def _home() -> Path:
    return Path.home()


def _env_path(name: str, default: Path) -> Path:
    v = os.environ.get(name)
    return Path(v).expanduser() if v else default


MIMO_DB = _env_path("MIMOCODE_DB", _home() / ".local" / "share" / "mimocode" / "mimocode.db")
CLAUDE_STAGING = _env_path("CONTEST_STAGING", _home() / ".claude" / "contest-collector-staging")
CLAUDE_ENV_FILE = _env_path("CONTEST_ENV_FILE", _home() / ".claude" / "contest-collector.env")
CODEX_SESSIONS = _env_path("CODEX_SESSIONS", _home() / ".codex" / "sessions")

# --------------------------------------------------------------------------------------
# 基础工具
# --------------------------------------------------------------------------------------


def now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (
        datetime.now(timezone.utc).microsecond // 1000
    )


def ms_to_iso(ms: Any) -> str:
    try:
        ms_int = int(ms)
    except Exception:
        return now_iso()
    dt = datetime.fromtimestamp(ms_int / 1000.0, tz=timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (ms_int % 1000)


def local_date(ts: Optional[str]) -> str:
    if not ts:
        return datetime.now().strftime("%Y-%m-%d")
    try:
        dt = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
        return dt.astimezone().strftime("%Y-%m-%d")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d")


def parse_ts(ts: Optional[str]) -> Optional[datetime]:
    if not ts:
        return None
    try:
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
    except Exception:
        return None


def is_under(path_str: str, root_str: str) -> bool:
    if not path_str:
        return False
    try:
        p = os.path.normcase(os.path.normpath(path_str)).rstrip("\\/")
        r = os.path.normcase(os.path.normpath(root_str)).rstrip("\\/")
    except Exception:
        return False
    return p == r or p.startswith(r + os.sep)


def find_workspace(start: Path) -> Path:
    """向上找 .repo（openvela 工作区标识）；找不到就返回起始目录。"""
    cur = start.resolve()
    for cand in [cur] + list(cur.parents):
        try:
            if (cand / ".repo").exists():
                return cand
        except Exception:
            continue
    return cur


def load_identity(env_file: Path) -> Tuple[str, str]:
    team_id, login = DEFAULT_TEAM_ID, DEFAULT_LOGIN
    try:
        if env_file.is_file():
            for line in env_file.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if line.startswith("TEAM_ID="):
                    v = line.split("=", 1)[1].strip().strip('"').strip("'")
                    if v:
                        team_id = v
                elif line.startswith("GITHUB_LOGIN="):
                    v = line.split("=", 1)[1].strip().strip('"').strip("'")
                    if v:
                        login = v
    except Exception:
        pass
    return team_id, login


# --------------------------------------------------------------------------------------
# 脱敏
# --------------------------------------------------------------------------------------

DEFAULT_REDACTION: List[Tuple[str, str]] = [
    (r"sk-[A-Za-z0-9_\-]{20,}", "sk-***REDACTED***"),
    (r"gh[pous]_[A-Za-z0-9]{20,}", "gh*_***REDACTED***"),
    (r"github_pat_[A-Za-z0-9_]{20,}", "github_pat_***REDACTED***"),
    (r"tp-[A-Za-z0-9]{20,}", "tp-***REDACTED***"),
    (r"xai-[A-Za-z0-9]{20,}", "xai-***REDACTED***"),
    (r"AKIA[0-9A-Z]{16}", "AKIA***REDACTED***"),
    (r"(?i)bearer\s+[A-Za-z0-9._\-+/=]{16,}", "Bearer ***REDACTED***"),
    (
        r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----",
        "***REDACTED PRIVATE KEY***",
    ),
    (
        r"(?i)((?:api[_-]?key|access[_-]?token|client[_-]?secret|password|passwd|secret)\s*[:=]\s*[\"']?)"
        r"([A-Za-z0-9._\-]{6,})",
        r"\1***REDACTED***",
    ),
]


class Redactor:
    def __init__(self, rules: List[Tuple[str, str]], enabled: bool = True) -> None:
        self.enabled = enabled
        self.rules = [(re.compile(pat), rep) for pat, rep in rules]

    def text(self, s: str) -> Tuple[str, int]:
        if not self.enabled or not s:
            return s, 0
        total = 0
        out = s
        for rx, rep in self.rules:
            out, n = rx.subn(rep, out)
            total += n
        return out, total

    def value(self, v: Any) -> Tuple[Any, int]:
        if not self.enabled:
            return v, 0
        if isinstance(v, str):
            return self.text(v)
        if isinstance(v, list):
            total = 0
            arr = []
            for item in v:
                nv, n = self.value(item)
                arr.append(nv)
                total += n
            return arr, total
        if isinstance(v, dict):
            total = 0
            d: Dict[str, Any] = {}
            for k, item in v.items():
                nv, n = self.value(item)
                d[k] = nv
                total += n
            return d, total
        return v, 0


def load_redaction_rules(member_dir: Path) -> List[Tuple[str, str]]:
    rules = list(DEFAULT_REDACTION)
    custom = member_dir / "redact.json"
    try:
        if custom.is_file():
            data = json.loads(custom.read_text(encoding="utf-8"))
            items = data.get("rules", data) if isinstance(data, dict) else data
            for r in items:
                if isinstance(r, dict) and r.get("pattern"):
                    rules.append((str(r["pattern"]), str(r.get("replacement", "***REDACTED***"))))
    except Exception:
        pass
    return rules


# --------------------------------------------------------------------------------------
# 会话模型
# --------------------------------------------------------------------------------------


class Session:
    def __init__(
        self,
        sid: str,
        tool: str,
        cwd: str,
        title: str,
        events: List[Dict[str, Any]],
        raw_count: int = 0,
        note: str = "",
    ) -> None:
        self.sid = sid
        self.tool = tool
        self.cwd = cwd
        self.title = title
        self.events = events
        self.raw_count = raw_count
        self.note = note
        self.first_ts = next((e["ts"] for e in events if e.get("ts")), None)
        self.last_ts = next((e["ts"] for e in reversed(events) if e.get("ts")), None)

    def date(self, mode: str) -> str:
        return local_date(self.last_ts if mode == "last" else self.first_ts)


# --------------------------------------------------------------------------------------
# 来源 1：MiMo Desktop / mimocode
# --------------------------------------------------------------------------------------


def _is_boilerplate_text(text: str) -> bool:
    t = (text or "").lstrip()
    return t.startswith("<system-reminder>")


def _compaction_text(part: Dict[str, Any]) -> str:
    proj = part.get("projection") or {}
    return str(proj.get("summary") or "")


def build_mimocode_session(
    conn: sqlite3.Connection,
    row: Any,
    max_io: int,
    include_compaction: bool,
) -> Optional[Session]:
    sid = row["id"]
    try:
        msgs = conn.execute(
            "SELECT id, data, time_created FROM message WHERE session_id=? ORDER BY time_created, rowid",
            (sid,),
        ).fetchall()
    except sqlite3.Error:
        return None
    if not msgs:
        return None

    parts_by_msg: Dict[str, List[Any]] = {}
    for p in conn.execute(
        "SELECT message_id, data, rowid FROM part WHERE session_id=? ORDER BY rowid", (sid,)
    ):
        parts_by_msg.setdefault(p["message_id"], []).append(p["data"])

    events: List[Dict[str, Any]] = []
    for msg in msgs:
        try:
            mdata = json.loads(msg["data"])
        except Exception:
            continue
        role = (mdata.get("role") or "").lower()
        ts = ms_to_iso(msg["time_created"])
        model = mdata.get("modelID") or (mdata.get("model") or {}).get("modelID") or ""
        tokens = mdata.get("tokens") or {}
        t_in = tokens.get("input") if isinstance(tokens.get("input"), int) else None
        t_out = tokens.get("output") if isinstance(tokens.get("output"), int) else None

        chunk: List[Dict[str, Any]] = []
        attachments: List[str] = []
        for raw in parts_by_msg.get(msg["id"], []):
            try:
                part = json.loads(raw)
            except Exception:
                continue
            ptype = part.get("type")

            if ptype == "text":
                text = part.get("text") or ""
                if not text.strip():
                    continue
                if role != "assistant" and _is_boilerplate_text(text):
                    continue
                chunk.append({"ts": ts, "role": "user" if role == "user" else role, "text": text})

            elif ptype == "reasoning":
                text = part.get("text") or ""
                if text.strip():
                    chunk.append({"ts": ts, "role": "assistant", "thinking": text})

            elif ptype == "tool":
                state = part.get("state") or {}
                status = state.get("status") or ""
                out_val = state.get("output")
                ev: Dict[str, Any] = {
                    "ts": ts,
                    "role": "tool",
                    "tool_name": part.get("tool") or "unknown",
                    "tool_call_id": part.get("callID") or "",
                    "input": state.get("input"),
                    "output": out_val if status == "completed" else None,
                    "metadata": {"status": status},
                }
                if status == "error":
                    ev["is_error"] = True
                chunk.append(ev)

            elif ptype == "file":
                name = part.get("filename") or part.get("path") or "attachment"
                mime = part.get("mime") or ""
                attachments.append(("%s (%s)" % (name, mime)).strip())

            elif ptype == "compaction":
                if include_compaction:
                    summary = _compaction_text(part)
                    if summary.strip():
                        chunk.append({"ts": ts, "role": "system", "text": summary})

            # step-start / step-finish / patch 等不单独成事件

        if attachments and chunk:
            for ev in chunk:
                if ev.get("role") == "user" and ev.get("text"):
                    ev.setdefault("files_touched", [])
                    ev["files_touched"] = list(attachments)
                    break

        if role == "assistant" and chunk:
            # 把该条消息的 tokens / model 挂到第一个事件上，避免重复计数
            first = chunk[0]
            if model:
                first["model"] = model
            if isinstance(t_in, int):
                first["tokens_in"] = t_in
            if isinstance(t_out, int):
                first["tokens_out"] = t_out

        if max_io > 0:
            for ev in chunk:
                for key in ("input", "output", "text", "thinking"):
                    if key in ev:
                        ev[key] = _limit_value(ev[key], max_io)

        events.extend(chunk)

    if not events:
        return None
    title = row["title"] if "title" in row.keys() else ""
    cwd = row["directory"] if "directory" in row.keys() else ""
    return Session(sid, "mimocode", cwd or "", title or "", events, raw_count=len(msgs))


def _limit_value(value: Any, limit: int) -> Any:
    if isinstance(value, str) and len(value) > limit:
        return value[:limit] + ("\n...[truncated %d chars]" % (len(value) - limit))
    return value


def load_mimocode_sessions(
    workspace: Path, allow_outside: bool, max_io: int, include_compaction: bool
) -> Tuple[List[Session], int, str]:
    if not MIMO_DB.is_file():
        return [], 0, "未找到 mimocode 数据库：%s" % MIMO_DB
    try:
        uri = "file:%s?mode=ro" % MIMO_DB.as_posix()
        conn = sqlite3.connect(uri, uri=True)
        conn.row_factory = sqlite3.Row
    except Exception as exc:
        return [], 0, "打开 mimocode.db 失败（%s）。请先完全退出 MiMo Desktop 再试。" % exc

    sessions: List[Session] = []
    skipped = 0
    try:
        rows = conn.execute(
            "SELECT id, directory, title, parent_id, time_created, time_updated "
            "FROM session ORDER BY time_created"
        ).fetchall()
        for row in rows:
            cwd = row["directory"] or ""
            if not allow_outside and not is_under(cwd, str(workspace)):
                skipped += 1
                continue
            sess = build_mimocode_session(conn, row, max_io, include_compaction)
            if sess is not None:
                sessions.append(sess)
    finally:
        conn.close()
    return sessions, skipped, ""


# --------------------------------------------------------------------------------------
# 来源 2：官方 collector 的 staging（claude-code / codex / opencode / cursor / kiro / mimocode）
# --------------------------------------------------------------------------------------


def load_staging_sessions(login: str) -> Tuple[List[Session], str]:
    root = CLAUDE_STAGING / login
    if not root.is_dir():
        return [], "未找到 staging 目录：%s（Claude Code 等工具需先安装官方采集钩子）" % root
    sessions: List[Session] = []
    for f in sorted(root.glob("*/*.jsonl")):
        name = f.name
        if "__" not in name:
            continue
        tool = name.split("__", 1)[0]
        if tool not in ALLOWED_TOOLS:
            continue
        events: List[Dict[str, Any]] = []
        try:
            with f.open("r", encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        ev = json.loads(line)
                    except Exception:
                        continue
                    ev.pop("schema_version", None)
                    ev.pop("seq", None)
                    if not ev.get("ts"):
                        continue
                    events.append(ev)
        except Exception:
            continue
        if not events:
            continue
        sid = f.stem.split("__", 1)[1]
        sessions.append(Session(sid, tool, "", name, events, raw_count=len(events)))
    return sessions, ""


# --------------------------------------------------------------------------------------
# 来源 3：Codex CLI 原始 rollout（可选）
# --------------------------------------------------------------------------------------


def _read_zst(path: Path) -> Optional[str]:
    try:
        import zstandard  # type: ignore

        with path.open("rb") as fh:
            dctx = zstandard.ZstdDecompressor()
            with dctx.stream_reader(fh) as reader:
                return reader.read().decode("utf-8", errors="replace")
    except ImportError:
        pass
    except Exception:
        return None
    try:
        import subprocess

        out = subprocess.run(["zstd", "-dc", str(path)], capture_output=True, check=False)
        if out.returncode == 0:
            return out.stdout.decode("utf-8", errors="replace")
    except Exception:
        pass
    return None


def load_codex_sessions(workspace: Path, allow_outside: bool) -> Tuple[List[Session], str]:
    if not CODEX_SESSIONS.is_dir():
        return [], "未找到 Codex sessions 目录：%s" % CODEX_SESSIONS
    files = sorted(CODEX_SESSIONS.glob("*/*/*/rollout-*.jsonl.zst"))
    if not files:
        return [], ""
    missing_zstd = 0
    sessions: List[Session] = []
    for f in files:
        raw = _read_zst(f)
        if raw is None:
            missing_zstd += 1
            continue
        events: List[Dict[str, Any]] = []
        cwd = ""
        sid = ""
        for line in raw.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except Exception:
                continue
            ts = rec.get("timestamp") or ""
            payload = rec.get("payload") or {}
            rtype = rec.get("type")
            if rtype == "session_meta":
                cwd = payload.get("cwd") or cwd
                sid = payload.get("id") or payload.get("session_id") or sid
                continue
            if rtype != "response_item":
                continue
            ptype = payload.get("type")
            if ptype == "message":
                role = (payload.get("role") or "").lower()
                if role not in ("user", "assistant"):
                    continue
                for blk in payload.get("content") or []:
                    if not isinstance(blk, dict):
                        continue
                    btype = blk.get("type")
                    text = blk.get("text") or ""
                    if not text:
                        continue
                    if btype in ("input_text", "output_text") or btype.startswith("text"):
                        events.append({"ts": ts, "role": role, "text": text})
            elif ptype == "reasoning":
                parts_text = []
                for sm in payload.get("summary") or []:
                    if isinstance(sm, dict) and sm.get("text"):
                        parts_text.append(sm["text"])
                if parts_text:
                    events.append({"ts": ts, "role": "assistant", "thinking": "\n".join(parts_text)})
            elif ptype == "function_call":
                args = payload.get("arguments")
                try:
                    args_obj = json.loads(args) if isinstance(args, str) else args
                except Exception:
                    args_obj = args
                events.append(
                    {
                        "ts": ts,
                        "role": "tool",
                        "tool_name": payload.get("name") or "unknown",
                        "tool_call_id": payload.get("call_id") or "",
                        "input": args_obj,
                        "output": None,
                    }
                )
            elif ptype == "function_call_output":
                events.append(
                    {
                        "ts": ts,
                        "role": "tool",
                        "tool_name": "<result>",
                        "tool_call_id": payload.get("call_id") or "",
                        "input": None,
                        "output": payload.get("output"),
                    }
                )
        if not events:
            continue
        if not allow_outside and cwd and not is_under(cwd, str(workspace)):
            continue
        if not sid:
            sid = f.name
        sessions.append(Session(sid, "codex", cwd, f.name, events, raw_count=len(events)))
    note = ""
    if missing_zstd:
        note = "有 %d 个 Codex 会话无法解压（缺 zstandard 模块或 zstd 命令），已跳过。" % missing_zstd
    return sessions, note


