def _dsh_content_text(content: Any) -> str:
    parts: List[str] = []
    if isinstance(content, list):
        for blk in content:
            if isinstance(blk, dict) and blk.get("type") == "text" and blk.get("text"):
                parts.append(str(blk["text"]))
    elif isinstance(content, str):
        parts.append(content)
    return "\\n".join(parts)


def build_dsh_events(events: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    call_names: Dict[str, str] = {}
    ordered = sorted(events, key=lambda e: e.get("seq", 0) if isinstance(e.get("seq"), int) else 0)
    for ev in ordered:
        etype = ev.get("type")
        data = ev.get("data") or {}
        ts = ms_to_iso(ev.get("time")) if ev.get("time") is not None else now_iso()

        if etype == "tool/call":
            if data.get("callId"):
                call_names[str(data["callId"])] = str(data.get("name") or "unknown")

        elif etype == "user/message":
            source = data.get("source") or {}
            if str(source.get("kind") or "") != "user":
                continue  # runtime-context / system 注入的不算用户发言
            for blk in data.get("content") or []:
                if isinstance(blk, dict) and blk.get("type") == "text":
                    text = str(blk.get("text") or "")
                    if text.strip():
                        out.append({"ts": ts, "role": "user", "text": text})

        elif etype == "assistant/message":
            msg = data.get("message") or {}
            usage = data.get("usage") or {}
            model = (data.get("source") or {}).get("model") or (msg.get("source") or {}).get("model") or ""
            chunk: List[Dict[str, Any]] = []
            for blk in msg.get("content") or []:
                if not isinstance(blk, dict):
                    continue
                btype = blk.get("type")
                if btype == "reasoning":
                    text = str(blk.get("text") or "")
                    if text.strip():
                        chunk.append({"ts": ts, "role": "assistant", "thinking": text})
                elif btype == "text":
                    text = str(blk.get("text") or "")
                    if text.strip():
                        chunk.append({"ts": ts, "role": "assistant", "text": text})
                elif btype == "tool-call":
                    raw_args = blk.get("arguments")
                    try:
                        args_obj = json.loads(raw_args) if isinstance(raw_args, str) else raw_args
                    except Exception:
                        args_obj = raw_args
                    cid = str(blk.get("id") or "")
                    chunk.append(
                        {
                            "ts": ts,
                            "role": "tool",
                            "tool_name": str(blk.get("name") or call_names.get(cid) or "unknown"),
                            "tool_call_id": cid,
                            "input": args_obj,
                            "output": None,
                        }
                    )
            if chunk:
                if model:
                    chunk[0]["model"] = model
                if isinstance(usage.get("inputTokens"), int):
                    chunk[0]["tokens_in"] = usage["inputTokens"]
                if isinstance(usage.get("outputTokens"), int):
                    chunk[0]["tokens_out"] = usage["outputTokens"]
                out.extend(chunk)

        elif etype == "tool/result":
            msg = data.get("message") or {}
            cid = str(
                data.get("toolCallId")
                or (msg.get("source") or {}).get("callId")
                or msg.get("toolCallId")
                or ""
            )
            text = _dsh_content_text(msg.get("content"))
            item: Dict[str, Any] = {
