 416: {
 417:   FILE *fp;
 418:   char line[256];
 419:   int n = 0;
 420:   int i;
 421:   int j;
 422: 
 423:   fp = fopen("/tmp/wifi_scan_result.txt", "r");
 424:   if (!fp)
 425:     {
 426:       return -1;
 427:     }
 428: 
 429:   pthread_mutex_lock(&s_lock);
 430:   s_ap_n = 0;
 431: 
 432:   while (fgets(line, sizeof(line), fp) && n < DM_WIFI_AP_MAX)
 433:     {
 434:       char *p = line;
 435:       char *tok_bssid;
 436:       char *tok_freq;
 437:       char *tok_rssi;
 438:       char *tok_enc;
 439:       char *ssid_start;
 440:       size_t ssid_len;
 441:       int rssi;
 442:       bool is_open;
 443:       int dup_idx = -1;
 444: 
 445:       line[strcspn(line, "\r\n")] = 0;
 446: 
 447:       while (*p == ' ' || *p == '\t')
 448:         {
 449:           p++;
 450:         }
 451:       if (!*p || strncmp(p, "bssid", 5) == 0)
 452:         {
 453:           continue;
 454:         }
 455: 
 456:       /* Field 0: BSSID (must contain ':') */
 457:       tok_bssid = p;
 458:       while (*p && *p != ' ' && *p != '\t')
 459:         {
 460:           p++;
 461:         }
 462:       if (!*p)
 463:         {
 464:           continue;
 465:         }
 466:       *p++ = 0;
 467:       if (strchr(tok_bssid, ':') == NULL)
 468:         {
 469:           continue;
 470:         }
 471: 
 472:       /* Field 1: frequency */
 473:       while (*p == ' ' || *p == '\t')
 474:         {
 475:           p++;
 476:         }
 477:       tok_freq = p;
 478:       while (*p && *p != ' ' && *p != '\t')
 479:         {
 480:           p++;
 481:         }
 482:       if (!*p || !*tok_freq)
 483:         {
 484:           continue;
 485:         }
 486:       *p++ = 0;
 487: 
 488:       /* Field 2: signal level (RSSI) */
 489:       while (*p == ' ' || *p == '\t')
 490:         {
 491:           p++;
 492:         }
 493:       tok_rssi = p;
 494:       while (*p && *p != ' ' && *p != '\t')
 495:         {
 496:           p++;
 497:         }
 498:       if (!*p || !*tok_rssi)
 499:         {
 500:           continue;
 501:         }
 502:       *p++ = 0;
 503:       rssi = atoi(tok_rssi);
 504: 
 505:       /* Field 3: encode (0000 = open, otherwise encrypted) */
 506:       while (*p == ' ' || *p == '\t')
 507:         {
 508:           p++;
 509:         }
 510:       tok_enc = p;
 511:       while (*p && *p != ' ' && *p != '\t')
 512:         {
 513:           p++;
 514:         }
 515:       if (*p)
 516:         {
 517:           *p++ = 0;
 518:         }
 519:       if (!*tok_enc)
 520:         {
 521:           continue;
 522:         }
 523:       is_open = (strcmp(tok_enc, "0000") == 0);
 524: 
 525:       /* Field 4+: entire remainder of line is SSID (may contain spaces) */
 526:       while (*p == ' ' || *p == '\t')
 527:         {
 528:           p++;
 529:         }
 530:       ssid_start = p;
 531:       ssid_len = strlen(ssid_start);
 532:       while (ssid_len > 0 &&
 533:              (ssid_start[ssid_len - 1] == ' ' ||
 534:               ssid_start[ssid_len - 1] == '\t'))
 535:         {
 536:           ssid_start[--ssid_len] = 0;
 537:         }
 538:       if (ssid_len == 0)
 539:         {
 540:           /* Hidden AP with blank SSID */
 541:           continue;
 542:         }
 543: 
 544:       /* Deduplicate by SSID: keep strongest RSSI */
 545:       for (i = 0; i < n; i++)
 546:         {
 547:           if (strncmp(s_aps[i].ssid, ssid_start, sizeof(s_aps[i].ssid) - 1) == 0)
 548:             {
 549:               dup_idx = i;
 550:               break;
 551:             }
 552:         }
 553:       if (dup_idx >= 0)
 554:         {
 555:           if (rssi > s_aps[dup_idx].rssi)
 556:             {
 557:               s_aps[dup_idx].rssi = rssi;
 558:               s_aps[dup_idx].open = is_open;
 559:             }
 560:           continue;
 561:         }
 562: 
 563:       strncpy(s_aps[n].ssid, ssid_start, sizeof(s_aps[n].ssid) - 1);
 564:       s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
 565:       s_aps[n].rssi = rssi;
 566:       s_aps[n].open = is_open;
 567:       n++;
 568:     }
 569: 
 570:   /* Sort APs by RSSI descending (strongest signal first) */
 571:   for (i = 0; i < n - 1; i++)
 572:     {
 573:       for (j = i + 1; j < n; j++)
 574:         {
 575:           if (s_aps[j].rssi > s_aps[i].rssi)
 576:             {
 577:               dm_ap_t tmp = s_aps[i];
 578:               s_aps[i] = s_aps[j];
 579:               s_aps[j] = tmp;
 580:             }
 581:         }
 582:     }
 583: 
 584:   s_ap_n = n;
 585:   if (s_sel >= s_ap_n)
 586:     {
 587:       s_sel = (s_ap_n > 0) ? 0 : -1;
 588:     }
 589:   pthread_mutex_unlock(&s_lock);
 590:   fclose(fp);
 591:   return n;
 592: }
