 679: /* Official connect — ifup → mode 2 → psk(3 2) → essid(1) → wait → renew */
 680: static void *conn_thread(void *arg)
 681: {
 682:   char cmd[192];
 683:   char qssid[80];
 684:   char qpass[160];
 685:   int i;
 686:   int got_ip = 0;
 687:   int is_auto = s_conn_is_auto;
 688:   struct in_addr addr;
 689:   char try_ssid[33];
 690:   char try_pass[64];
 691:   bool try_open;
 692: 
 693:   (void)arg;
 694: 
 695:   strncpy(try_ssid, s_pending_ssid, sizeof(try_ssid) - 1);
 696:   try_ssid[sizeof(try_ssid) - 1] = 0;
 697:   strncpy(try_pass, s_pending_pass, sizeof(try_pass) - 1);
 698:   try_pass[sizeof(try_pass) - 1] = 0;
 699:   try_open = s_pending_open;
 700: 
 701:   if (try_ssid[0] == 0 || if_nametoindex(DM_WIFI_IF) == 0)
 702:     {
 703:       syslog(LOG_ERR, "[deskmate-wifi] connect abort: no ssid/wlan0\n");
 704:       s_conn_busy = 0;
 705:       s_conn_fail = 1;
 706:       return NULL;
 707:     }
 708: 
 709:   if (ensure_driver() < 0)
 710:     {
 711:       s_conn_busy = 0;
 712:       s_conn_fail = 1;
 713:       return NULL;
 714:     }
 715: 
 716:   if (is_auto && s_manual_override)
 717:     {
 718:       s_conn_busy = 0;
 719:       return NULL;
 720:     }
 721: 
 722:   /* Save credentials to /data/wifi.cfg first (compatible with 9.5 wifi_manager) */
 723:   if (!is_auto)
 724:     {
 725:       wifi_cred_save(try_ssid, try_pass);
 726:     }
 727: 
 728:   /* 1) ifup + STA mode */
 729:   cli_sta_up();
 730: 
 731:   /* 2) psk — WPA_ALG_CCMP = 3, WPA2 = 2 */
 732:   if (!try_open && try_pass[0])
 733:     {
 734:       if (shell_quote(try_pass, qpass, sizeof(qpass)) < 0)
 735:         {
 736:           s_conn_busy = 0;
 737:           s_conn_fail = 1;
 738:           return NULL;
 739:         }
 740:       snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3 2", DM_WIFI_IF, qpass);
 741:       syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
 742:       (void)system(cmd);
 743:     }
 744: 
 745:   /* 3) essid — flag 1 = connect */
 746:   if (shell_quote(try_ssid, qssid, sizeof(qssid)) < 0)
 747:     {
 748:       s_conn_busy = 0;
 749:       s_conn_fail = 1;
 750:       return NULL;
 751:     }
 752:   snprintf(cmd, sizeof(cmd), "wapi essid %s %s 1", DM_WIFI_IF, qssid);
 753:   syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
 754:   (void)system(cmd);
 755: 
 756:   /* 4) Wait for WPA2 4-way handshake / association (interruptible if auto) */
 757:   for (i = 0; i < 25; i++)
 758:     {
 759:       if (is_auto && s_manual_override)
 760:         {
 761:           s_conn_busy = 0;
 762:           return NULL;
 763:         }
 764:       usleep(100 * 1000);
 765:     }
 766: 
 767:   /* 5) DHCP renew — single DHCP call per attempt */
 768:   for (i = 0; i < 4; i++)
 769:     {
 770:       if (is_auto && s_manual_override)
 771:         {
 772:           s_conn_busy = 0;
 773:           return NULL;
 774:         }
 775: 
 776:       (void)system("renew wlan0");
 777:       if (wifi_get_valid_ip(&addr) == 0)
 778:         {
 779:           got_ip = 1;
 780:           break;
 781:         }
 782: 
 783:       if (is_auto && s_manual_override)
 784:         {
 785:           s_conn_busy = 0;
 786:           return NULL;
 787:         }
 788: 
 789:       if (netlib_obtain_ipv4addr(DM_WIFI_IF) >= 0 &&
 790:           wifi_get_valid_ip(&addr) == 0)
 791:         {
 792:           got_ip = 1;
 793:           break;
 794:         }
 795: 
 796:       syslog(LOG_WARNING, "[deskmate-wifi] renew retry %d\n", i + 1);
 797:       sleep(1);
 798:     }
 799: 
 800:   /* Fix: Only set s_cur_ssid when got_ip is true! */
 801:   pthread_mutex_lock(&s_lock);
 802:   if (got_ip)
 803:     {
 804:       strncpy(s_cur_ssid, try_ssid, sizeof(s_cur_ssid) - 1);
 805:       s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
 806:       strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
 807:       s_cur_ip[sizeof(s_cur_ip) - 1] = 0;
 808:     }
 809:   else
 810:     {
 811:       s_cur_ssid[0] = 0;
 812:       s_cur_ip[0] = 0;
 813:     }
 814:   pthread_mutex_unlock(&s_lock);
 815: 
 816:   if (!got_ip)
 817:     {
 818:       syslog(LOG_ERR,
 819:              "[deskmate-wifi] connect fail: no IP after renew "
 820:              "(ssid=%s wlan0=%d)\n",
 821:              try_ssid, (int)if_nametoindex(DM_WIFI_IF));
 822:       s_conn_busy = 0;
 823:       if (!is_auto)
 824:         {
 825:           s_conn_fail = 1;
 826:         }
 827:       return NULL;
 828:     }
 829: 
 830:   syslog(LOG_INFO, "[deskmate-wifi] connected ssid=%s ip=%s\n",
 831:          s_cur_ssid, s_cur_ip);
 832: 
 833:   (void)system("wapi save_config wlan0");
 834:   wifi_cred_save(try_ssid, try_pass);
 835: 
 836:   s_conn_busy = 0;
 837:   s_conn_ok = 1;
 838:   return NULL;
 839: }
