 846:   int ret;
 847:   int i;
 848: 
 849:   if (!ssid || !ssid[0])
 850:     {
 851:       return -1;
 852:     }
 853: 
 854:   if (!is_auto)
 855:     {
 856:       s_manual_override = 1;
 857:       for (i = 0; i < 50 && (s_scan_busy || (s_conn_busy && s_conn_is_auto)); i++)
 858:         {
