 869:   s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
 870:   if (pass)
 871:     {
 872:       strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
 873:       s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
 874:     }
 875:   else
 876:     {
