  49:         while (fgets(buffer, sizeof(buffer), fp) != NULL) {
  50:             // 检查是否包含"not connected"
  51:             if (strstr(buffer, "AP: 00:00:00:00:00:00") != NULL) {
  52:                 status = 1; // 返回1表示未连接
