static void pw_ok(lv_event_t *e)
{
  const char *pw;
  (void)e;

  pw = s_pw_in ? lv_textarea_get_text(s_pw_in) : "";
  if (pw)
    {
      strncpy(s_pw_buf, pw, sizeof(s_pw_buf) - 1);
      s_pw_buf[sizeof(s_pw_buf) - 1] = 0;
    }
  else
    {
      s_pw_buf[0] = 0;
    }

  /* Validate the password before calling wapi: "wapi psk" only accepts
   * 8..63 characters, so shorter/longer values would fail inside the shell
   * command with a confusing "connect failed" result. */
  if (!s_sel_open)
    {
      size_t pwlen = strlen(s_pw_buf);
      if (pwlen < 8 || pwlen > 63)
        {
          if (s_pw_ssid_l)
            {
              char msg[64];
              lv_snprintf(msg, sizeof(msg), "%s (%s)", s_sel_ssid,
                          pwlen == 0
                              ? dm_t("请输入密码", "Enter password")
                              : dm_t("密码需 8-63 位", "Password 8-63 chars"));
              lv_label_set_text(s_pw_ssid_l, msg);
            }
          return;
        }
    }

  if (dm_wifi_connect(s_sel_ssid, s_pw_buf) == 0)
    {
      if (s_conn_ssid_l)
        {
          lv_label_set_text(s_conn_ssid_l, s_sel_ssid);
        }
      dm_show(PAGE_WIFI_CONN);
    }
  else if (s_pw_ssid_l)
    {
      char msg[64];
      lv_snprintf(msg, sizeof(msg), "%s (%s)", s_sel_ssid,
                  dm_t("设备忙，请稍后重试", "Busy, retry"));
      lv_label_set_text(s_pw_ssid_l, msg);
    }
}

