// 2) brace / paren balance check (strip comments & strings)
function balance(file) {
  let t = fs.readFileSync(file,'utf8');
  let out = '';
  for (let i=0;i<t.length;i++) {
    const c=t[i], n=t[i+1];
    if (c==='/' && n==='/') { while (i<t.length && t[i]!=='\n') i++; out+='\n'; continue; }
    if (c==='/' && n==='*') { i+=2; while (i<t.length && !(t[i]==='*'&&t[i+1]==='/')) i++; i++; continue; }
    if (c==='"' || c==="'") { const q=c; out+=' '; i++; while (i<t.length) { if (t[i]==='\\') { i+=2; continue; } if (t[i]===q) break; i++; } continue; }
    out+=c;
  }
  const count = (ch) => out.split(ch).length - 1;
  return { file: file.split('\\').pop(), lbrace: count('{'), rbrace: count('}'), lparen: count('('), rparen: count(')') };
}
