# -*- coding: utf-8 -*-
"""COM5 @1500000 调试 Gemini-S1 / FlowDesk：跑一组 NSH 诊断命令并保存全部输出。"""
import sys, time, os
from datetime import datetime
try:
    import serial
except ImportError:
    print("NO_PYSERIAL")
    sys.exit(2)

PORT = sys.argv[1] if len(sys.argv) > 1 else "COM5"
BAUD = int(sys.argv[2]) if len(sys.argv) > 2 else 1500000
OUT = sys.argv[3] if len(sys.argv) > 3 else os.path.join(os.path.dirname(__file__), "..", "notes", "com5_debug.txt")

def dec(b):
    try:
        return b.decode("utf-8", "replace")
    except Exception:
        return str(b)

def main():
    ser = serial.Serial(PORT, BAUD, bytesize=8, parity="N", stopbits=1, timeout=0.2, write_timeout=3)
    ser.reset_input_buffer()
    log = []
    def w(s):
        log.append(s)
        print(s, flush=True)
    def read_for(seconds):
        end = time.time() + seconds
        buf = b""
        while time.time() < end:
            try:
                chunk = ser.read(4096)
            except Exception:
                break
            if chunk:
                buf += chunk
                end = time.time() + 0.35   # keep reading while data flows
        return dec(buf)
    def cmd(c, wait=1.5):
        try:
            ser.reset_input_buffer()
        except Exception:
            pass
        ser.write((c + "\\r\\n").encode())
        time.sleep(0.15)
        return read_for(wait)

    w("==== COM5 %d open %s ====" % (BAUD, datetime.now().isoformat(timespec="seconds")))
    # wake up prompt
    ser.write(b"\\r\\n"); time.sleep(0.4); wake = read_for(0.8)
    w("---- wake ----\\n" + wake)

    plan = [
        ("ifconfig", 1.5),
        ("ls /dev", 1.5),
        ("gpio /dev/gpio2", 1.0),
        ("gpio -t 1 /dev/gpio2", 1.0),
        ("gpio /dev/gpio3", 1.0),
        ("test_wifi init", 6.0),
        ("ifconfig", 2.0),
        ("wapi show wlan0", 2.0),
        ("ls /data/etc/wifi", 1.2),
        ("ls /resource/etc/wifi", 1.2),
        ("dmesg", 4.0),
        ("free", 1.0),
        ("ps", 2.0),
        ("uptime", 0.8),
    ]
    for c, wait in plan:
        w("\\n==== CMD: %s ====" % c)
        w(cmd(c, wait))

    try:
        ser.close()
    except Exception:
        pass
    os.makedirs(os.path.dirname(os.path.abspath(OUT)), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        f.write("\\n".join(log))
    w("\\n==== saved: %s ====" % os.path.abspath(OUT))

if __name__ == "__main__":
    main()
`;
