# -*- coding: utf-8 -*-
"""COM5 后台抓取：等开发板重启（烧录后）→ 抓完整启动日志（带 WiFi 驱动调试）
→ 看到 nsh> 后再执行 ifconfig / ls /dev / test_wifi init / ifconfig 并保存。"""
import time, os, sys
import serial

PORT="COM5"; BAUD=1500000
OUT=os.path.join(os.path.dirname(__file__), "..", "notes", "com5_boot_debug.txt")
WAIT_TOTAL=480.0
ser=serial.Serial(PORT,BAUD,timeout=0.3,write_timeout=3)
ser.reset_input_buffer()
buf=[]
t0=time.time(); prompts=0; last_data=time.time()
f=open(OUT,"w",encoding="utf-8")
def flush(s):
    buf.append(s); f.write(s+"\\n"); f.flush()
flush("==== capture start %s (waiting for board reboot/flash) ====" % time.strftime("%Y-%m-%d %H:%M:%S"))
try:
    while time.time()-t0 < WAIT_TOTAL:
        try: chunk=ser.read(8192)
        except Exception: break
        if chunk:
            s=chunk.decode("utf-8","replace")
            f.write(s); f.flush()
            last_data=time.time()
            prompts += s.count("nsh>")
            if prompts>=2 and (time.time()-last_data)>2.0:
                break
        time.sleep(0.05)
    flush("==== boot capture done, prompts=%d elapsed=%.1fs ====" % (prompts, time.time()-t0))
    # post-boot diagnostics
    def rd(sec):
        end=time.time()+sec; b=b""
        while time.time()<end:
            try: c=ser.read(4096)
            except Exception: break
            if c: b+=c; end=time.time()+0.4
        return b.decode("utf-8","replace")
    def cmd(c,wt=3.0):
        try: ser.reset_input_buffer()
        except Exception: pass
        ser.write((c+"\\r\\n").encode()); time.sleep(0.15); return rd(wt)
    f.write("\\r\\n"); time.sleep(0.5); rd(0.5)
    for c,wt in [("ifconfig",2.0),("ls /dev",2.0),("test_wifi init",6.0),("ifconfig",2.0)]:
        flush("\\n==== CMD: %s ====" % c)
        f.write(cmd(c,wt)); f.flush()
    flush("==== capture end ====")
except Exception as e:
    f.write("\\nCAPTURE ERROR: %r\\n" % (e,)); f.flush()
finally:
    try: ser.close()
    except Exception: pass
    f.close()
`;
