# -*- coding: utf-8 -*-
"""COM5 抓烧录后启动日志（带 WiFi 驱动 debug），随后跑诊断命令。"""
import time, os, sys
import serial
OUT=os.path.join(os.path.dirname(__file__),"..","notes","com5_boot_debug.txt")
MAXWAIT=float(sys.argv[1]) if len(sys.argv)>1 else 260.0
def main():
    try:
        ser=serial.Serial("COM5",1500000,timeout=0.3,write_timeout=3)
    except Exception as e:
        print("OPEN_FAIL", repr(e)); return 2
    ser.reset_input_buffer()
    f=open(OUT,"w",encoding="utf-8")
    f.write("==== capture start %s (max %.0fs) ====\\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), MAXWAIT)); f.flush()
    t0=time.time(); got=0; prompts=0; last=time.time()
    try:
        while time.time()-t0 < MAXWAIT:
            try: c=ser.read(8192)
            except Exception: break
            if c:
                s=c.decode("utf-8","replace"); f.write(s); f.flush()
                got+=len(c); prompts+=s.count("nsh>"); last=time.time()
                if prompts>=2 and time.time()-last>1.5:
                    break
            time.sleep(0.03)
        f.write("\\n==== boot capture done got=%d prompts=%d elapsed=%.1f ====\\n" % (got,prompts,time.time()-t0)); f.flush()
        if prompts:
            def rd(sec):
                end=time.time()+sec; b=b""
                while time.time()<end:
                    try: cc=ser.read(4096)
                    except Exception: break
                    if cc: b+=cc; end=time.time()+0.4
                return b.decode("utf-8","replace")
            def cmd(c,wt):
                try: ser.reset_input_buffer()
                except Exception: pass
                ser.write((c+"\\r\\n").encode()); time.sleep(0.15); return rd(wt)
            f.write("\\r\\n"); time.sleep(0.4); rd(0.4)
            for c,wt in [("ifconfig",2.0),("ls /dev",2.0),("test_wifi init",8.0),("ifconfig",2.0),("wapi show wlan0",2.0)]:
                f.write("\\n==== CMD: %s ====\\n" % c); f.flush()
                f.write(cmd(c,wt)); f.flush()
        f.write("\\n==== capture end ====\\n")
    finally:
        try: ser.close()
        except Exception: pass
        f.close()
    print("DONE got=%d prompts=%d elapsed=%.1f" % (got,prompts,time.time()-t0))
if __name__=="__main__": sys.exit(main())
