 321:  * 76:39:89:fe:f0:ad       2462    -85     0803
 322:  * d2:ad:08:f8:eb:71       2462    -88     0803    DIRECT-71-HP Smart Tank 750
 323:  * 7c:c8:4a:e9:39:f8       5180    -92     0803    yankemei168_5G
 324:  * 7c:c8:4a:e9:39:fb       5180    -92     0805
 325:  * c8:50:e9:bb:f5:0a       2422    -93     0803    ChinaNet-sqJr
 326:  */
 327: static int get_wifi_ssids(char ap_names[][32], int max_count)
 328: {
 329:     FILE *fp;
 330:     char line[256];
 331:     int count = 0;
 332:     
 333:     // 打开/tmp/wifi_scan_result.txt文件
 334:     fp = fopen("/tmp/wifi_scan_result.txt", "r");
 335:     if (fp == NULL) {
 336:         // 文件不存在或无法打开，返回0
 337:         return 0;
 338:     }
 339:     
 340:     // 跳过第一行标题
 341:     if (fgets(line, sizeof(line), fp) == NULL) {
 342:         fclose(fp);
 343:         return 0;
 344:     }
 345:     
 346:     // 逐行读取文件内容
 347:     while (fgets(line, sizeof(line), fp) != NULL && count < max_count) {
 348:         char *token;
 349:         int field_count = 0;
 350:         char *saveptr = NULL;
 351:         
 352:         // 去除行尾的换行符
 353:         char *newline = strchr(line, '\n');
 354:         if (newline) {
 355:             *newline = '\0';
 356:         }
 357:         
 358:         // 使用空格分割字段
 359:         token = strtok_r(line, " \t", &saveptr);
 360:         while (token != NULL && field_count < 5) {
 361:             // 第5个字段是SSID（索引为4）
 362:             if (field_count == 4) {
 363:                 // 复制SSID到ap_names数组中
 364:                 strncpy(ap_names[count], token, 31);
 365:                 ap_names[count][31] = '\0'; // 确保字符串结束
 366:                 count++;
 367:                 break;
 368:             }
 369:             token = strtok_r(NULL, " \t", &saveptr);
 370:             field_count++;
 371:         }
 372:     }
 373:     
 374:     fclose(fp);
 375:     return count;
 376: }
