static void manual_ok(lv_event_t *e)
{
  const char *ssid = s_manual_ssid_in
                         ? lv_textarea_get_text(s_manual_ssid_in)
                         : NULL;
  const char *pw = s_manual_pw_in
                       ? lv_textarea_get_text(s_manual_pw_in)
                       : NULL;
  char ssid_buf[33];
  char pw_buf[64];
  size_t pwlen;

  (void)e;
  ssid_buf[0] = 0;
  pw_buf[0] = 0;
  if (ssid != NULL)
    {
      strncpy(ssid_buf, ssid, sizeof(ssid_buf) - 1);
      ssid_buf[sizeof(ssid_buf) - 1] = 0;
    }
  if (pw != NULL)
    {
      strncpy(pw_buf, pw, sizeof(pw_buf) - 1);
      pw_buf[sizeof(pw_buf) - 1] = 0;
    }

  if (ssid_buf[0] == 0)
    {
      set_manual_tip("请输入 WiFi 名称", "Enter the SSID");
      return;
    }

  /* "wapi psk" only accepts 8..63 characters. */
  pwlen = strlen(pw_buf);
  if (pwlen > 0 && (pwlen < 8 || pwlen > 63))
    {
      set_manual_tip("密码需 8-63 位", "Password must be 8-63 chars");
      return;
    }

  if (dm_wifi_connect(ssid_buf, pwlen > 0 ? pw_buf : NULL) == 0)
    {
      if (s_conn_ssid_l)
        {
          lv_label_set_text(s_conn_ssid_l, ssid_buf);
        }
      dm_show(PAGE_WIFI_CONN);
    }
  else
    {
      set_manual_tip("设备忙，请稍后重试", "Busy, retry");
    }
}

static void manual_ta_event_cb(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);
  lv_obj_t *ta = lv_event_get_target(e);
  lv_obj_t *kb = (lv_obj_t *)lv_event_get_user_data(e);

  if (code == LV_EVENT_CLICKED || code == LV_EVENT_FOCUSED)
    {
      if (kb != NULL)
        {
          lv_keyboard_set_textarea(kb, ta);
        }
    }
  else if (code == LV_EVENT_READY)
    {
      manual_ok(e);
    }
  else if (code == LV_EVENT_CANCEL)
    {
      dm_show(PAGE_WIFI);
    }
}

