        len = getline(&buffer, &size, stdin);
        if (-1 == len) {
            bttool_quit(&bttool);
            break;
        }

        buffer[len] = '\0';
        if (buffer[0] == '!') {
#ifdef CONFIG_SYSTEM_SYSTEM
            system(buffer + 1);
#endif
            continue;
        }

        if (buffer[len - 1] == '\n')
            buffer[len - 1] = '\0';

        if (strcmp(buffer, "quit") == 0 || strcmp(buffer, "q") == 0) {
