 17: /* Simple challenge generator */
 18: static uint32_t dm_bt_gen_challenge(void)
 19: {
 20:   return (uint32_t)(rand() ^ (uintptr_t)&s_pair_state);
 21: }
 22: 
 23: /* Compute response from challenge + key */
 24: static uint32_t dm_bt_compute_response(uint32_t challenge)
 25: {
 26:   uint32_t h = 0;
 27:   const char *k = DM_BT_PAIR_KEY;
 28:   int i;
 29:   for (i = 0; i < DM_BT_PAIR_KEY_LEN; i++)
 30:     h = h * 31 + (uint8_t)k[i];
 31:   return challenge ^ h;
 32: }
 33: 
 34: /* Verify response */
 35: int dm_bt_verify_pair(uint32_t challenge, uint32_t response)
 36: {
 37:   uint32_t expected = dm_bt_compute_response(challenge);
 38:   syslog(LOG_INFO, "[bt-pair] challenge=0x%x resp=0x%x expected=0x%x\n",
 39:          challenge, response, expected);
 40:   return (response == expected) ? 0 : -1;
 41: }
 42: 
 43: /* Generate auth message: CMD + challenge */
 44: int dm_bt_build_pair_req(uint8_t *buf, size_t buflen, uint32_t challenge)
 45: {
 46:   if (buflen < 6) return -1;
 47:   buf[0] = DM_BT_CMD_PAIR_REQ;
 48:   buf[1] = 4; /* data len */
 49:   memcpy(buf + 2, &challenge, 4);
 50:   return 6;
 51: }
 52: 
 53: /* Parse auth response */
