const code = String.raw`/****************************************************************************
 * sal_pan_interface.c - PAN (BNEP over BR/EDR L2CAP) SAL backend
 *
 * Implements the PAN profile data path for the zblue stack:
 *   - opens a BR/EDR ACL link to the peer (PANU -> NAP)
 *   - opens the BNEP L2CAP channel (PSM 0x000F)
 *   - performs the BNEP setup handshake
 *   - forwards Ethernet frames between panu_service's TAP interface and BNEP
 *
 * NOTE: zblue has no built-in BNEP, so the protocol is implemented here on
 * top of the public BR/EDR L2CAP API.
 ****************************************************************************/
#define LOG_TAG "sal_pan"

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include <zephyr/bluetooth/bluetooth.h>
#include <zephyr/bluetooth/buf.h>
#include <zephyr/bluetooth/conn.h>
#include <zephyr/bluetooth/hci_types.h>
#include <zephyr/bluetooth/l2cap.h>
#include <zephyr/kernel.h>
#include <zephyr/net_buf.h>

#include "adapter_internel.h"
#include "sal_pan_interface.h"
#include "utils/log.h"

#define BNEP_PSM             0x000F
#define BNEP_MTU             CONFIG_BT_L2CAP_TX_MTU
#define BNEP_HDR_MAX         15

/* BNEP packet types */
#define BNEP_GENERAL         0x00
#define BNEP_CONTROL         0x01
#define BNEP_COMPRESSED      0x02
#define BNEP_COMPRESSED_SRC  0x03
#define BNEP_COMPRESSED_DST  0x04
#define BNEP_TYPE_MASK       0x7F
#define BNEP_EXT_HEADER      0x80

/* BNEP control types */
#define BNEP_CMD_NOT_UNDERSTOOD  0x00
#define BNEP_SETUP_CONN_REQ      0x01
#define BNEP_SETUP_CONN_RSP      0x02
#define BNEP_FILTER_NET_TYPE_SET 0x03
#define BNEP_FILTER_NET_TYPE_RSP 0x04
#define BNEP_FILTER_MULTI_SET    0x05
#define BNEP_FILTER_MULTI_RSP    0x06

#define BNEP_SUCCESS         0x0000

/* PAN service UUIDs (16 bit) */
#define BNEP_SVC_PANU        0x1115
#define BNEP_SVC_NAP         0x1116
#define BNEP_SVC_GN          0x1117

#define PAN_SETUP_TIMEOUT    K_SECONDS(9)
#define PAN_SETUP_RETRIES    3

NET_BUF_POOL_FIXED_DEFINE(bnep_tx_pool, 6,
                          BT_L2CAP_BUF_SIZE(BNEP_MTU),
                          CONFIG_BT_CONN_TX_USER_DATA_SIZE, NULL);

typedef struct
{
  bool inited;
  bool connected; /* BNEP setup completed */
  struct bt_conn *conn;
  bt_address_t peer;
  pan_role_t local_role;
  pan_role_t remote_role;
  uint8_t local_mac[6];
  uint8_t remote_mac[6];
  struct bt_l2cap_br_chan chan;
  struct k_work_delayable setup_work;
  uint8_t setup_attempts;
} pan_sal_t;

static pan_sal_t g_pan;
static struct bt_l2cap_server g_bnep_server;
static struct bt_conn_cb g_pan_conn_cb;

static void pan_setup_work_handler(struct k_work *work);

/****************************************************************************
 * Small helpers
 ****************************************************************************/

static void pan_addr_to_mac(const bt_address_t *addr, uint8_t mac[6])
{
  int i;

  for (i = 0; i < 6; i++)
    {
      mac[i] = addr->addr[5 - i];
    }
}

static uint16_t pan_role_uuid(pan_role_t role)
{
  switch (role)
    {
      case PAN_ROLE_NAP:
        return BNEP_SVC_NAP;
      case PAN_ROLE_PANU:
        return BNEP_SVC_PANU;
      case PAN_ROLE_GN:
        return BNEP_SVC_GN;
      default:
        return BNEP_SVC_PANU;
    }
}

static int bnep_send(const uint8_t *data, uint16_t len)
{
  struct net_buf *buf;
  int err;

  if (!g_pan.conn || len == 0 || len > BNEP_MTU)
    {
      return -EINVAL;
    }

  buf = net_buf_alloc(&bnep_tx_pool, K_NO_WAIT);
  if (buf == NULL)
    {
      return -ENOMEM;
    }

  net_buf_reserve(buf, BT_L2CAP_CHAN_SEND_RESERVE);
  net_buf_add_mem(buf, data, len);

  err = bt_l2cap_chan_send(&g_pan.chan.chan, buf);
  if (err < 0)
    {
      net_buf_unref(buf);
    }

  return err;
}

static int bnep_send_ctrl(uint8_t ctrl, uint16_t value)
{
  uint8_t frame[4];

  frame[0] = BNEP_CONTROL;
  frame[1] = ctrl;
  frame[2] = (uint8_t)(value >> 8);
  frame[3] = (uint8_t)(value & 0xff);
  return bnep_send(frame, sizeof(frame));
}

static int bnep_send_setup_req(void)
{
  uint8_t frame[7];
  uint16_t src;
  uint16_t dst;

  src = pan_role_uuid(g_pan.local_role);
  dst = pan_role_uuid(g_pan.remote_role);

  frame[0] = BNEP_CONTROL;
  frame[1] = BNEP_SETUP_CONN_REQ;
  frame[2] = 0x02; /* 16-bit UUID size */
  frame[3] = (uint8_t)(src >> 8);
  frame[4] = (uint8_t)(src & 0xff);
  frame[5] = (uint8_t)(dst >> 8);
  frame[6] = (uint8_t)(dst & 0xff);

  return bnep_send(frame, sizeof(frame));
}

static void pan_notify(profile_connection_state_t state)
{
  pan_on_connection_state_changed(&g_pan.peer, g_pan.remote_role,
                                  g_pan.local_role, state);
}

static void pan_release_conn(void)
{
  if (g_pan.conn != NULL)
    {
      bt_conn_unref(g_pan.conn);
      g_pan.conn = NULL;
    }

  memset(&g_pan.chan, 0, sizeof(g_pan.chan));
  g_pan.connected = false;
  k_work_cancel_delayable(&g_pan.setup_work);
}

static void pan_mark_connected(void)
{
  if (g_pan.connected)
    {
      return;
    }

  g_pan.connected = true;
  k_work_cancel_delayable(&g_pan.setup_work);
  BT_LOGI("BNEP setup done, peer connected");
  pan_notify(PROFILE_STATE_CONNECTED);
}

static void pan_mark_failed(void)
{
  if (!g_pan.connected)
    {
      pan_notify(PROFILE_STATE_DISCONNECTED);
    }

  if (g_pan.chan.chan.conn != NULL)
    {
      bt_l2cap_chan_disconnect(&g_pan.chan.chan);
    }

  pan_release_conn();
}

/****************************************************************************
 * BNEP receive path
 ****************************************************************************/

static void bnep_rx_control(const uint8_t *data, uint16_t len)
{
  uint8_t ctrl;

  if (len < 2)
    {
      return;
    }

  ctrl = data[1];
  switch (ctrl)
    {
      case BNEP_SETUP_CONN_REQ:
        /* Accept an incoming setup request (NAP role) and answer success. */
        bnep_send_ctrl(BNEP_SETUP_CONN_RSP, BNEP_SUCCESS);
        pan_mark_connected();
        break;

      case BNEP_SETUP_CONN_RSP:
        if (len >= 4)
          {
            uint16_t resp = ((uint16_t)data[2] << 8) | data[3];
            if (resp == BNEP_SUCCESS)
              {
                pan_mark_connected();
              }
            else
              {
                BT_LOGW("BNEP setup rejected: 0x%04x", resp);
                pan_mark_failed();
              }
          }
        break;

      case BNEP_FILTER_NET_TYPE_SET:
        bnep_send_ctrl(BNEP_FILTER_NET_TYPE_RSP, BNEP_SUCCESS);
        break;

      case BNEP_FILTER_MULTI_SET:
        bnep_send_ctrl(BNEP_FILTER_MULTI_RSP, BNEP_SUCCESS);
        break;

      default:
        bnep_send_ctrl(BNEP_CMD_NOT_UNDERSTOOD, ctrl);
        break;
    }
}

static void bnep_rx_frame(const uint8_t *data, uint16_t len)
{
  uint8_t type;
  uint16_t proto;

  if (len < 1)
    {
      return;
    }

  type = data[0] & BNEP_TYPE_MASK;

  switch (type)
    {
      case BNEP_CONTROL:
        bnep_rx_control(data, len);
        break;

      case BNEP_GENERAL:
        if (len < BNEP_HDR_MAX)
          {
            return;
          }

        proto = ((uint16_t)data[13] << 8) | data[14];
        pan_on_data_received(&g_pan.peer, proto, (uint8_t *)&data[1],
                             (uint8_t *)&data[7], (uint8_t *)&data[BNEP_HDR_MAX],
                             (uint16_t)(len - BNEP_HDR_MAX));
        break;

      case BNEP_COMPRESSED:
        if (len < 3)
          {
            return;
          }

        proto = ((uint16_t)data[1] << 8) | data[2];
        pan_on_data_received(&g_pan.peer, proto, g_pan.local_mac,
                             g_pan.remote_mac, (uint8_t *)&data[3],
                             (uint16_t)(len - 3));
        break;

      case BNEP_COMPRESSED_SRC:
        if (len < 9)
          {
            return;
          }

        proto = ((uint16_t)data[7] << 8) | data[8];
        pan_on_data_received(&g_pan.peer, proto, (uint8_t *)&data[1],
                             g_pan.remote_mac, (uint8_t *)&data[9],
                             (uint16_t)(len - 9));
        break;

      case BNEP_COMPRESSED_DST:
        if (len < 9)
          {
            return;
          }

        proto = ((uint16_t)data[7] << 8) | data[8];
        pan_on_data_received(&g_pan.peer, proto, g_pan.local_mac,
                             (uint8_t *)&data[1], (uint8_t *)&data[9],
                             (uint16_t)(len - 9));
        break;

      default:
        break;
    }
}

/****************************************************************************
 * L2CAP channel callbacks
 ****************************************************************************/

static void bnep_chan_connected(struct bt_l2cap_chan *chan)
{
  (void)chan;
  BT_LOGI("BNEP L2CAP channel connected");

  if (g_pan.local_role == PAN_ROLE_PANU)
    {
      g_pan.setup_attempts = 0;
      if (bnep_send_setup_req() == 0)
        {
          g_pan.setup_attempts = 1;
          k_work_reschedule(&g_pan.setup_work, PAN_SETUP_TIMEOUT);
        }
      else
        {
          pan_mark_failed();
        }
    }
}

static void bnep_chan_disconnected(struct bt_l2cap_chan *chan)
{
  (void)chan;
  BT_LOGI("BNEP L2CAP channel disconnected");
  pan_notify(PROFILE_STATE_DISCONNECTED);
  pan_release_conn();
}

static int bnep_chan_recv(struct bt_l2cap_chan *chan, struct net_buf *buf)
{
  (void)chan;

  if (buf == NULL)
    {
      return -EINVAL;
    }

  bnep_rx_frame(buf->data, buf->len);
  net_buf_unref(buf);
  return 0;
}

static struct bt_l2cap_chan_ops g_bnep_chan_ops =
{
  .connected = bnep_chan_connected,
  .disconnected = bnep_chan_disconnected,
  .recv = bnep_chan_recv,
};

/****************************************************************************
 * BR/EDR connection / L2CAP setup
 ****************************************************************************/

static int pan_start_l2cap(struct bt_conn *conn)
{
  int err;

  memset(&g_pan.chan, 0, sizeof(g_pan.chan));
  g_pan.chan.chan.conn = conn;
  g_pan.chan.chan.ops = &g_bnep_chan_ops;
  g_pan.chan.rx.mtu = BT_L2CAP_RX_MTU;
  g_pan.chan.required_sec_level = BT_SECURITY_L2;

  err = bt_l2cap_chan_connect(conn, &g_pan.chan.chan, BNEP_PSM);
  if (err < 0)
    {
      BT_LOGW("bnep l2cap connect failed: %d", err);
    }

  return err;
}

static void pan_conn_connected(struct bt_conn *conn, uint8_t err)
{
  if (conn != g_pan.conn)
    {
      return;
    }

  if (err != 0)
    {
      BT_LOGW("BR/EDR connection failed: 0x%02x", err);
      pan_mark_failed();
      return;
    }

  (void)pan_start_l2cap(conn);
}

static void pan_conn_disconnected(struct bt_conn *conn, uint8_t reason)
{
  if (conn != g_pan.conn)
    {
      return;
    }

  BT_LOGI("BR/EDR link disconnected: 0x%02x", reason);
  pan_notify(PROFILE_STATE_DISCONNECTED);
  pan_release_conn();
}

static int pan_server_accept(struct bt_conn *conn,
                             struct bt_l2cap_server *server,
                             struct bt_l2cap_chan **chan)
{
  (void)server;

  if (g_pan.conn != NULL || chan == NULL)
    {
      return -ENOMEM;
    }

  g_pan.conn = bt_conn_ref(conn);
  memset(&g_pan.chan, 0, sizeof(g_pan.chan));
  g_pan.chan.chan.conn = conn;
  g_pan.chan.chan.ops = &g_bnep_chan_ops;
  g_pan.chan.rx.mtu = BT_L2CAP_RX_MTU;
  *chan = &g_pan.chan.chan;
  return 0;
}

static void pan_setup_work_handler(struct k_work *work)
{
  (void)work;

  if (g_pan.connected || g_pan.conn == NULL)
    {
      return;
    }

  if (g_pan.setup_attempts >= PAN_SETUP_RETRIES)
    {
      BT_LOGW("BNEP setup timeout");
      pan_mark_failed();
      return;
    }

  if (bnep_send_setup_req() == 0)
    {
      g_pan.setup_attempts++;
      k_work_reschedule(&g_pan.setup_work, PAN_SETUP_TIMEOUT);
    }
  else
    {
      pan_mark_failed();
    }
}

static int pan_conn_is_connected(struct bt_conn *conn)
{
  struct bt_conn_info info;

  if (bt_conn_get_info(conn, &info) < 0)
    {
      return 0;
    }

  return info.state == BT_CONN_CONNECTED;
}

/****************************************************************************
 * Public SAL API
 ****************************************************************************/

bt_status_t bt_sal_pan_init(uint8_t max_conn, pan_role_t role)
{
  int err;

  (void)max_conn;

  if (g_pan.inited)
    {
      return BT_STATUS_SUCCESS;
    }

  memset(&g_pan, 0, sizeof(g_pan));
  g_pan.local_role = role;
  g_pan.remote_role = (role == PAN_ROLE_PANU) ? PAN_ROLE_NAP : PAN_ROLE_PANU;
  g_pan.setup_work.work = (struct k_work){0};
  k_work_init_delayable(&g_pan.setup_work, pan_setup_work_handler);

  g_pan_conn_cb.connected = pan_conn_connected;
  g_pan_conn_cb.disconnected = pan_conn_disconnected;
  err = bt_conn_cb_register(&g_pan_conn_cb);
  if (err < 0)
    {
      BT_LOGE("bt_conn_cb_register failed: %d", err);
    }

  g_bnep_server.psm = BNEP_PSM;
  g_bnep_server.sec_level = BT_SECURITY_L2;
  g_bnep_server.accept = pan_server_accept;
  err = bt_l2cap_br_server_register(&g_bnep_server);
  if (err < 0)
    {
      BT_LOGW("BNEP L2CAP server register failed: %d", err);
    }

  g_pan.inited = true;
  BT_LOGI("PAN SAL initialized, role=%d", role);
  return BT_STATUS_SUCCESS;
}

bt_status_t bt_sal_pan_cleanup(void)
{
  if (!g_pan.inited)
    {
      return BT_STATUS_SUCCESS;
    }

  if (g_pan.chan.chan.conn != NULL)
    {
      bt_l2cap_chan_disconnect(&g_pan.chan.chan);
    }

  if (g_pan.conn != NULL)
    {
      bt_conn_disconnect(g_pan.conn, BT_HCI_ERR_REMOTE_USER_TERM_CONN);
    }

  bt_conn_cb_unregister(&g_pan_conn_cb);
  pan_release_conn();
  g_pan.inited = false;
  return BT_STATUS_SUCCESS;
}

bt_status_t bt_sal_pan_connect(bt_address_t *addr, uint8_t dst_role,
                               uint8_t src_role)
{
  struct bt_conn *conn;

  if (!g_pan.inited || addr == NULL)
    {
      return BT_STATUS_NOT_ENABLED;
    }

  if (g_pan.conn != NULL)
    {
      return BT_STATUS_BUSY;
    }

  g_pan.peer = *addr;
  g_pan.local_role = (pan_role_t)src_role;
  g_pan.remote_role = (pan_role_t)dst_role;

  if (g_pan.local_role > PAN_ROLE_PANU)
    {
      g_pan.local_role = PAN_ROLE_PANU;
    }

  if (g_pan.remote_role == PAN_ROLE_NONE)
    {
      g_pan.remote_role = PAN_ROLE_NAP;
    }

  pan_addr_to_mac(addr, g_pan.remote_mac);
  {
    bt_address_t local;
    adapter_get_address(&local);
    pan_addr_to_mac(&local, g_pan.local_mac);
  }

  conn = bt_conn_lookup_addr_br((const bt_addr_t *)addr);
  if (conn != NULL)
    {
      g_pan.conn = conn;
      if (pan_conn_is_connected(conn))
        {
          (void)pan_start_l2cap(conn);
        }
      /* else: wait for the connected callback */
      return BT_STATUS_SUCCESS;
    }

  conn = bt_conn_create_br((const bt_addr_t *)addr,
                           BT_BR_CONN_PARAM_DEFAULT);
  if (conn == NULL)
    {
      BT_LOGE("bt_conn_create_br failed");
      return BT_STATUS_FAIL;
    }

  g_pan.conn = conn;
  return BT_STATUS_SUCCESS;
}

bt_status_t bt_sal_pan_disconnect(bt_address_t *addr)
{
  (void)addr;

  if (!g_pan.inited)
    {
      return BT_STATUS_NOT_ENABLED;
    }

  if (g_pan.chan.chan.conn != NULL)
    {
      bt_l2cap_chan_disconnect(&g_pan.chan.chan);
    }
  else if (g_pan.conn != NULL)
    {
      bt_conn_disconnect(g_pan.conn, BT_HCI_ERR_REMOTE_USER_TERM_CONN);
    }

  pan_notify(PROFILE_STATE_DISCONNECTED);
  pan_release_conn();
  return BT_STATUS_SUCCESS;
}

bt_status_t bt_sal_pan_write(bt_address_t *addr, uint16_t proto,
                             uint8_t *dst_addr, uint8_t *src_addr,
                             uint8_t *data, uint16_t length)
{
  uint8_t frame[BNEP_MTU];
  uint16_t total;

  (void)addr;

  if (!g_pan.connected || dst_addr == NULL || src_addr == NULL ||
      data == NULL)
    {
      return BT_STATUS_FAIL;
    }

  total = (uint16_t)(1 + 6 + 6 + 2 + length);
  if (total > BNEP_MTU)
    {
      BT_LOGW("BNEP frame too large: %u", total);
      return BT_STATUS_FAIL;
    }

  frame[0] = BNEP_GENERAL;
  memcpy(&frame[1], dst_addr, 6);
  memcpy(&frame[7], src_addr, 6);
  frame[13] = (uint8_t)(proto >> 8);
  frame[14] = (uint8_t)(proto & 0xff);
  memcpy(&frame[BNEP_HDR_MAX], data, length);

  if (bnep_send(frame, total) < 0)
    {
      return BT_STATUS_FAIL;
    }

  return BT_STATUS_SUCCESS;
}
