#include "service_loop.h"
#include "utils/log.h"

#include "sal_pan_interface.h"      /* bt_pan.h + pan_service.h */

#ifdef CONFIG_BLUETOOTH_BREDR_SUPPORT

#define PAN_BNEP_PSM              0x000F
#define PAN_BNEP_MTU              1691
#define PAN_UUID_PANU             0x1115
#define PAN_UUID_NAP              0x1116

#define PAN_GENERAL               0x00
#define PAN_CONTROL               0x01
#define PAN_COMPRESSED            0x02
#define PAN_COMPRESSED_SRC        0x03
#define PAN_COMPRESSED_DST        0x04
#define PAN_TYPE_MASK             0x7F
#define PAN_EXT_HEADER            0x80

#define PAN_CMD_NOT_UNDERSTOOD    0x00
#define PAN_SETUP_REQ             0x01
#define PAN_SETUP_RSP             0x02
#define PAN_FILTER_NET_SET        0x03
#define PAN_FILTER_NET_RSP        0x04
#define PAN_FILTER_MULTI_SET      0x05
#define PAN_FILTER_MULTI_RSP      0x06

#define PAN_SUCCESS               0x0000
#define PAN_CONN_NOT_ALLOWED      0x0004

#define PAN_HDR_GENERAL           (1 + 6 + 6 + 2)   /* 15 */
#define PAN_HDR_COMPRESSED        3
#define PAN_SETUP_TIMEOUT_MS      20000
#define PAN_SETUP_MAX_RETRIES     3

typedef enum {
    PAN_STATE_IDLE = 0,
    PAN_STATE_ACL_CONNECTING,
    PAN_STATE_L2CAP_CONNECTING,
    PAN_STATE_BNEP_SETUP,
    PAN_STATE_CONNECTED,
} pan_state_t;

typedef struct {
    bool used;
    uint8_t state;
    bt_address_t addr;
    uint8_t peer_mac[6];
    uint8_t local_mac[6];
    uint8_t local_role;
    uint8_t peer_role;
    bool disconn_reported;
    uint8_t setup_retries;
    service_timer_t *setup_timer;
    struct bt_l2cap_br_chan br_chan;
} pan_conn_t;

static pan_conn_t g_pan_conn[CONFIG_BT_MAX_CONN];
static pthread_mutex_t g_pan_lock;
static bool g_pan_ready;
static bool g_pan_cb_registered;
static bool g_pan_server_registered;
static uint8_t g_pan_local_role;

NET_BUF_POOL_DEFINE(pan_tx_pool, CONFIG_BT_MAX_CONN + 1,
    BT_L2CAP_BUF_SIZE(CONFIG_BT_L2CAP_TX_MTU),
    CONFIG_BT_CONN_TX_USER_DATA_SIZE, NULL);

static int pan_l2cap_accept(struct bt_conn *conn, struct bt_l2cap_server *server,
    struct bt_l2cap_chan **chan);
static void pan_chan_connected(struct bt_l2cap_chan *chan);
static void pan_chan_disconnected(struct bt_l2cap_chan *chan);
static int pan_chan_recv(struct bt_l2cap_chan *chan, struct net_buf *buf);
static void pan_conn_connected(struct bt_conn *conn, uint8_t err);
static void pan_conn_disconnected(struct bt_conn *conn, uint8_t reason);

static const struct bt_l2cap_chan_ops g_pan_chan_ops = {
    .connected = pan_chan_connected,
    .disconnected = pan_chan_disconnected,
    .recv = pan_chan_recv,
};

static struct bt_l2cap_server g_pan_server = {
    .psm = PAN_BNEP_PSM,
    .sec_level = BT_SECURITY_L2,
    .accept = pan_l2cap_accept,
};

static struct bt_conn_cb g_pan_conn_cb = {
    .connected = pan_conn_connected,
    .disconnected = pan_conn_disconnected,
};

/* ------------------------------------------------------------------ utils */

static uint16_t pan_be16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }

static void pan_put_be16(uint8_t *p, uint16_t v) { p[0] = (uint8_t)(v >> 8); p[1] = (uint8_t)v; }

static pan_conn_t *pan_find_by_addr(const bt_address_t *addr)
{
    for (size_t i = 0; i < CONFIG_BT_MAX_CONN; i++)
        if (g_pan_conn[i].used && !memcmp(&g_pan_conn[i].addr, addr, sizeof(*addr)))
            return &g_pan_conn[i];
    return NULL;
}

static pan_conn_t *pan_find_by_conn(struct bt_conn *conn)
{
    struct bt_conn_info info;

    if (bt_conn_get_info(conn, &info) || !info.br.dst)
        return NULL;
    for (size_t i = 0; i < CONFIG_BT_MAX_CONN; i++) {
        pan_conn_t *pc = &g_pan_conn[i];
        if (pc->used && !memcmp(pc->addr.addr, info.br.dst->val, 6))
            return pc;
    }
    return NULL;
}

static void pan_notify_disconnected(pan_conn_t *pc)
{
    if (pc->disconn_reported)
        return;
    pc->disconn_reported = true;
    pan_on_connection_state_changed(&pc->addr, pc->peer_role, pc->local_role,
        PROFILE_STATE_DISCONNECTED);
}

static void pan_reset(pan_conn_t *pc)
{
    if (pc->setup_timer) {
        service_loop_cancel_timer(pc->setup_timer);
        pc->setup_timer = NULL;
    }
    pc->state = PAN_STATE_IDLE;
    pc->setup_retries = 0;
}

static void pan_fail(pan_conn_t *pc)
{
    if (pc->br_chan.chan.conn)
        bt_l2cap_chan_disconnect(&pc->br_chan.chan);
    else
        pan_reset(pc);
    pan_notify_disconnected(pc);
}

/* ------------------------------------------------------------------- send */

static struct net_buf *pan_buf_alloc(size_t len)
{
    struct net_buf *buf = net_buf_alloc(&pan_tx_pool, K_NO_WAIT);

    if (!buf)
        return NULL;
    net_buf_reserve(buf, BT_L2CAP_CHAN_SEND_RESERVE);
    if (net_buf_tailroom(buf) < len) {
        net_buf_unref(buf);
        return NULL;
    }
    return buf;
}

static int pan_send(pan_conn_t *pc, struct net_buf *buf)
{
    int err;

    if (!buf)
        return -ENOMEM;
    err = bt_l2cap_chan_send(&pc->br_chan.chan, buf);
    if (err) {
        BT_LOGE("l2cap send failed err=%d", err);
        net_buf_unref(buf);
    }
    return err;
}

static int pan_send_ctrl(pan_conn_t *pc, uint8_t ctrl, const uint8_t *payload, uint16_t len)
{
    struct net_buf *buf = pan_buf_alloc(2u + len);
    uint8_t *p;

    if (!buf)
        return -ENOMEM;
    p = net_buf_add(buf, 2);
    p[0] = PAN_CONTROL;
    p[1] = ctrl;
    if (len)
        net_buf_add_mem(buf, payload, len);
    return pan_send(pc, buf);
}

static int pan_send_setup_req(pan_conn_t *pc)
{
    uint8_t p[5];

    p[0] = 0x02;                    /* uuid_size = 2 (16-bit UUIDs) */
    pan_put_be16(&p[1], PAN_UUID_NAP);   /* destination = peer role */
    pan_put_be16(&p[3], PAN_UUID_PANU);  /* source = local role     */
    return pan_send_ctrl(pc, PAN_SETUP_REQ, p, sizeof(p));
}

static int pan_send_filter_rsp(pan_conn_t *pc, uint8_t ctrl, uint16_t result)
{
    uint8_t p[2];

    pan_put_be16(p, result);
    return pan_send_ctrl(pc, ctrl, p, sizeof(p));
}

/* --------------------------------------------------------------- connect  */

static void pan_l2cap_connect(pan_conn_t *pc)
{
    struct bt_conn *conn;
    struct bt_conn_info info;
    int err;

    memset(&pc->br_chan, 0, sizeof(pc->br_chan));
    pc->br_chan.chan.ops = &g_pan_chan_ops;
    pc->br_chan.rx.mtu = BT_L2CAP_RX_MTU;

    conn = bt_conn_lookup_addr_br((const bt_addr_t *)&pc->addr);
    if (!conn) {
        pan_fail(pc);
        return;
    }
    if (bt_conn_get_info(conn, &info) || info.state != BT_CONN_STATE_CONNECTED) {
        bt_conn_unref(conn);
        return;                         /* conn_cb.connected will retry */
    }

    err = bt_l2cap_chan_connect(conn, &pc->br_chan.chan, PAN_BNEP_PSM);
    bt_conn_unref(conn);

    if (err == 0)
        pc->state = PAN_STATE_L2CAP_CONNECTING;
    else if (err != -ENOTCONN) {
        BT_LOGE("l2cap connect err=%d", err);
        pan_fail(pc);
    }
}

static void pan_l2cap_connect_async(void *data)
{
    pan_conn_t *pc = data;

    pthread_mutex_lock(&g_pan_lock);
    if (g_pan_ready && pc->used && pc->state == PAN_STATE_ACL_CONNECTING)
        pan_l2cap_connect(pc);
    pthread_mutex_unlock(&g_pan_lock);
}

/* -------------------------------------------------------------- callbacks */

static void pan_conn_connected(struct bt_conn *conn, uint8_t err)
{
    pan_conn_t *pc;

    if (!bt_conn_get_dst_br(conn))
        return;                                  /* LE conn, not ours */

    pthread_mutex_lock(&g_pan_lock);
    pc = pan_find_by_conn(conn);
    if (pc && pc->used && pc->state == PAN_STATE_ACL_CONNECTING) {
        if (err) {
            BT_LOGE("ACL connect failed err=0x%02x", err);
            pan_fail(pc);
        } else {
            do_in_service_loop(pan_l2cap_connect_async, pc);
        }
    }
    pthread_mutex_unlock(&g_pan_lock);
}

