 979: static int wifi_start_connect_internal(const char *ssid, const char *pass,
 980:                                        int is_auto)
 981: {
 982:   pthread_t th;
 983:   pthread_attr_t attr;
 984:   int ret;
 985:   int i;
 986: 
 987:   if (!ssid || !ssid[0])
 988:     {
 989:       return -1;
 990:     }
 991: 
 992:   if (!is_auto)
 993:     {
 994:       s_manual_override = 1;
 995:       for (i = 0; i < 50 && (s_scan_busy || (s_conn_busy && s_conn_is_auto)); i++)
 996:         {
 997:           usleep(100 * 1000);
 998:         }
 999:     }
1000: 
1001:   if (s_scan_busy || s_conn_busy)
1002:     {
1003:       return -1;
1004:     }
1005: 
1006:   strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
1007:   s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
1008:   if (pass)
1009:     {
1010:       strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
1011:       s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
1012:     }
1013:   else
1014:     {
1015:       s_pending_pass[0] = 0;
1016:     }
1017:   s_pending_open = (pass == NULL || s_pending_pass[0] == 0);
1018: 
1019:   s_conn_ok = 0;
1020:   s_conn_fail = 0;
1021:   s_conn_is_auto = is_auto;
1022:   s_conn_busy = 1;
1023: 
1024:   pthread_attr_init(&attr);
1025:   pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1026:   ret = pthread_create(&th, &attr, conn_thread, NULL);
1027:   pthread_attr_destroy(&attr);
1028:   if (ret != 0)
1029:     {
1030:       s_conn_busy = 0;
1031:       return -1;
1032:     }
1033:   pthread_detach(th);
1034:   return 0;
1035: }
